package dev.voyage.workbench;
import android.content.Context;import android.security.keystore.*;import android.util.Base64;import java.security.*;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;
final class Secrets {
 final Context app;Secrets(Context c){app=c;}
 private java.security.Key key(boolean create)throws Exception{KeyStore k=KeyStore.getInstance("AndroidKeyStore");k.load(null);if(!k.containsAlias("voyage-api")){if(!create)throw new GeneralSecurityException("Android secure storage key is unavailable. Reconnect your API key.");KeyGenerator g=KeyGenerator.getInstance("AES","AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder("voyage-api",KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());g.generateKey();}return k.getKey("voyage-api",null);}
 String get()throws Exception{return get("voyage");}
 String get(String name)throws Exception{String value=app.getSharedPreferences("secrets",0).getString(name,"");if(value.isEmpty())return "";String[] parts=value.split(":");boolean bound=parts.length==3&&"v2".equals(parts[0]);if(!bound&&parts.length!=2)throw new GeneralSecurityException("Android secure storage entry is invalid. Reconnect your API key.");int offset=bound?1:0;Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,key(false),new GCMParameterSpec(128,Base64.decode(parts[offset],0)));if(bound)c.updateAAD(name.getBytes(java.nio.charset.StandardCharsets.UTF_8));return new String(c.doFinal(Base64.decode(parts[offset+1],0)),java.nio.charset.StandardCharsets.UTF_8);}
 void set(String value)throws Exception{set("voyage",value);}
 void set(String name,String value)throws Exception{android.content.SharedPreferences.Editor editor=app.getSharedPreferences("secrets",0).edit();if(value.isEmpty()){if(!editor.remove(name).commit())throw new java.io.IOException("Could not remove the API key from Android secure storage.");return;}Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,key(true));c.updateAAD(name.getBytes(java.nio.charset.StandardCharsets.UTF_8));String encoded="v2:"+Base64.encodeToString(c.getIV(),Base64.NO_WRAP)+":"+Base64.encodeToString(c.doFinal(value.getBytes(java.nio.charset.StandardCharsets.UTF_8)),Base64.NO_WRAP);if(!editor.putString(name,encoded).commit())throw new java.io.IOException("Could not save the API key to Android secure storage.");}
}
